; Room start position, burst traps, score to BCD, register save
; $3217-$331b

; Puts Bruce at the start position of room X and enters that room. Input: X = room number (0-19).
; Sets current_actor = 0 (Bruce), next_room = X, and loads the start position from spawn_a_x/spawn_a_y,X.
; Then it jumps to enter_room, which stores the position, sets room, draws the room, resets the stack and
; enters the main loop. It does not return.
; Callers: lose_fall (respawn in the same room), draw_room (the room 11 shortcut to room 13) and room19_frame
; (back to room 0 for the next game loop).
place_bruce_at_room_start
        lda #$00
        sta current_actor               ; actor index 0 = Bruce
        txa
        sta next_room                   ; destination room
        lda spawn_a_y,x                 ; start Y of the room
        tay
        lda spawn_a_x,x                 ; start X of the room
        jmp enter_room                  ; room change: store X/Y, draw room, main loop
; Updates the three burst trap slots (floor traps that erupt after an actor touches them).
; A slot starts when an actor touches trap char $60 whose colour is not 5 (touch_trap_tile): the slot counter
; burst_trap_timer+n becomes 1, the cell above-left of the touched cell goes to burst_trap_row+n (row) and
; burst_trap_col+n (column), and the touched cell gets colour 5 so it does not trigger again.
; Each call increments every active counter (0 = slot free). By the counter value before the increment:
;   $08: tiles $2F/$30 (chars $F1-$F6, 3 wide x 2 rows) and sound $8D
;   $0C: tiles $31/$32 (chars $F7-$FC)
;   $10: tiles $2F/$30 again (no sound)
;   $14: top row blank (tile 0), bottom row tile $33 (chars $FD $E0 $FD) with colour 8 on its middle cell, so the
;        trap char $60 is armed again
;   $18: counter = 0, slot free.
; The burst chars $71-$7C kill an actor on contact (handle_touched_tile).
; Called by the frame handlers of rooms 6, 7, 10, 11, 12, 14, 16 and 17. Uses burst_slot as the slot index (2..0).
update_burst_traps
        ldx #$02
        stx burst_slot                  ; slot index 2..0
update_burst_traps_slot
        ldx burst_slot
        lda burst_trap_timer,x          ; slot counter, 0 = free
        bne update_burst_traps_active
        jmp update_burst_traps_next
update_burst_traps_active
        inc burst_trap_timer,x          ; A keeps the value before the increment
        cmp #$08                        ; stage 1: small burst
        bne update_burst_traps_stage_large
; Stage $08: play the burst sound, then draw the small burst.
        jsr play_burst_sound
; Draw tile $2F at (row, column) and tile $30 one row below.
update_burst_traps_draw_small
        ldx burst_slot
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        lda #$2f                        ; tile $2F: chars F1 F2 F3
        jsr print_message
        ldx burst_slot
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        inx
        lda #$30                        ; tile $30: chars F4 F5 F6
        jsr print_message
        jmp update_burst_traps_next
update_burst_traps_stage_large
        cmp #$0c                        ; stage 2: large burst
        bne update_burst_traps_stage_small2
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        lda #$31                        ; tile $31: chars F7 F8 F9
        jsr print_message
        ldx burst_slot
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        inx
        lda #$32                        ; tile $32: chars FA FB FC
        jsr print_message
        jmp update_burst_traps_next
update_burst_traps_stage_small2
        cmp #$10                        ; stage 3: small burst again
        beq update_burst_traps_draw_small
        cmp #$14                        ; stage 4: settle
        bne update_burst_traps_stage_free
; Stage $14: blank the top row, colour the middle cell of the bottom row with colour 8, draw the debris tile.
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        lda #$00                        ; tile 0: three blank cells
        jsr print_message
; The draw left Y = column + 3. Y - 2 = middle column; row_ptr_top + $4C50 = colour RAM two screen rows lower.
        dey
        dey
        lda row_ptr_top
        clc
        adc #<($d800 - game_screen + 80)
        sta row_ptr_top
        lda row_ptr_top+1
        adc #>($d800 - game_screen + 80) ; game_screen + $4C00 = $D800 colour RAM
        sta row_ptr_top+1
        lda #$f8                        ; colour 8: the trap char $60 is armed again
        sta (row_ptr_top),y
        ldx burst_slot
        ldy burst_trap_col,x
        lda burst_trap_row,x
        tax
        inx
        lda #$33                        ; tile $33: chars FD E0 FD
        jsr print_message
        jmp update_burst_traps_next
update_burst_traps_stage_free
        cmp #$18                        ; stage 5: slot free
        bne update_burst_traps_next
        lda #$00
        sta burst_trap_timer,x
update_burst_traps_next
        dec burst_slot
        bmi update_burst_traps_done
        jmp update_burst_traps_slot
update_burst_traps_done
        rts
; Plays sound effect $8D (burst trap) through play_sound. Keeps A, X and Y.
play_burst_sound
        pha
        txa
        pha
        tya
        pha
        ldy #$8d                        ; sound effect $8D
        jsr play_sound
        pla
        tay
        pla
        tax
        pla
        rts
; Converts the score to decimal digits for the status line.
; Input: score, a 24-bit binary number (high byte first).
; Output: 8 packed BCD digits in bcd_conv_digits..bcd_conv_digits+3 (high to low). Work copy of the score in
; bcd_conv_binary..+2.
; Method: shift the binary number left 24 times; after each shift double the BCD value in decimal mode and add
; the carry. Keeps the decimal flag state of the caller (PHP/PLP).
score_to_bcd
        ldx #$02
score_to_bcd_copy
        lda score,x
        sta bcd_conv_binary,x
        lda #$00
        sta bcd_conv_digits,x
        dex
        bpl score_to_bcd_copy
        sta bcd_conv_digits+3           ; clears the top BCD byte; A = 0
        php
        sed                             ; decimal mode for the doubling
        ldx #$17                        ; 24 bits
score_to_bcd_bit_loop
        asl bcd_conv_binary+2
        rol bcd_conv_binary+1
        rol bcd_conv_binary
        ldy #$03
score_to_bcd_digit_loop
        lda bcd_conv_digits,y           ; BCD = BCD*2 + carry, from the low byte up
        adc bcd_conv_digits,y
        sta bcd_conv_digits,y
        dey
        bpl score_to_bcd_digit_loop
        dex
        bpl score_to_bcd_bit_loop
        plp
        rts
; Saves A, X and Y in saved_a, saved_x and saved_y. Used around the lantern pickup check.
save_axy_zp
        sta saved_a
        stx saved_x
        sty saved_y
        rts
; Loads A, X and Y back from saved_a, saved_x and saved_y.
restore_axy_zp
        lda saved_a
        ldx saved_x
        ldy saved_y
        rts
